# -*- coding: utf-8 -*-
"""English translations, batch 4 (40 figures)."""
EN = {
"西拉": dict(lesson="Praise in prison",
 summary="Paul's missionary companion; beaten and locked with his feet in stocks in the inner cell of the Philippian jail, at midnight he prayed and sang with Paul; the prisoners heard, an earthquake came, the prison doors flew open, and the jailer believed in Christ and was baptized with his whole household.",
 witness="Acts records: about midnight Paul and Silas were praying and singing hymns to God, and the prisoners were listening. Their praise was no performance, but a true overflow of faith in the deepest pain and darkness—and that praise became a freeing power.",
 follow=["Choosing praise rather than complaint in the most painful situation","Facing unjust suffering with prayer and praise, not responding with hatred","Supporting his fellow worker in trouble, worshipping God together"],
 caution=[],
 applications=["Midnight praise—what is your darkest situation today? Will you praise God there?","The prisoners all heard—your praise is not only for yourself; those around watch how you respond to suffering","The earthquake opened the doors—praise can open doors you thought shut tight","Write down a suffering you're going through, then deliberately thank God for it"],
 prayer="Lord, Silas chose praise in stocks and darkness. Help me choose praise in today's pain and injustice too, trusting You still work in the dark, and that praise is the key that opens chains. Amen."),
"提多": dict(lesson="A co-worker who can be entrusted with hard tasks",
 summary="A Gentile believer, Paul's true son, sent to the chaotic church in Crete to set things in order and appoint elders; Paul described him as zealous in serving God's people, one of Paul's most trusted envoys, once sent to handle the thorny crisis in Corinth.",
 witness="Paul wrote: I left you in Crete that you might set in order what was lacking. Titus was entrusted with the hardest task—the Cretans were known for dishonesty, yet he was to build an honest church there.",
 follow=["Accepting being sent to the hardest place, not picking the easy field","Bringing order to chaos, building solid leadership in a weak community","Leading by example, a model of good works in everything"],
 caution=[],
 applications=["Titus was sent to the hardest place—is God sending you to a difficult situation today?","'Set in order what was lacking'—what 'lacking thing' is waiting for you to handle today?","Titus was entrusted because of character—what character are you building today?","Becoming trustworthy is not by talent, but by faithfulness and character"],
 prayer="Lord, Titus was sent to the hardest place yet faithfully finished the task. Help me too be willing to go where I'm most needed, becoming a co-worker of solid character who can be entrusted with hard things. Amen."),
"底马": dict(lesson="Love of the world leading to forsaking service",
 summary="A co-worker of Paul who in the end forsook Paul and ministry out of love for the world.",
 witness="Demas' story is a real warning that love of the world can lead to forsaking service. Long service does not equal final faithfulness.",
 follow=[],
 caution=["Once a co-worker of Paul (Col 4:14; Philem 24), with a good start","Yet forsaking Paul for Thessalonica out of 'love for this present world' (2 Tim 4:10), leaving at Paul's neediest, imprisoned hour","Not one fatal great sin, but being pulled away little by little by the world's allure"],
 applications=["A good start does not guarantee a good finish—beware the world's slow erosion of commitment","Whether you stay faithful at others' neediest, least glamorous moment best tests what's real","Examine regularly: what worldly thing is quietly pulling me away from God and service?"],
 prayer="Lord, protect me from giving up on You in the final stretch because of the world's allure. Amen."),
"拿但业": dict(lesson="No deceit is the foundation of faith",
 summary="A Galilean; when Philip invited him to come see Jesus he asked bluntly, can anything good come from Nazareth? On seeing him Jesus said, behold, a true Israelite, in whom there is no deceit; when Nathanael asked how do you know me, Jesus said, before Philip called you, I saw you—and he at once confessed: You are the Son of God!",
 witness="Jesus said to him: in you there is no deceit. This is one of Jesus' highest commendations of a disciple's character. Nathanael's bluntness sometimes looked like doubt, but his heart held no scheming, no hypocrisy—exactly the character Jesus most treasures.",
 follow=["Facing God and people with truth and frankness, not flattering with false words","Still willing to come see Jesus amid doubt, rather than refusing","Confessing wholeheartedly at once when Jesus revealed Himself, without delay"],
 caution=[],
 applications=["Nathanael's doubt was honest, not pretended faith—what real question can you bring straight to Jesus?","No deceit in his heart—is there anything two-faced in your faith today?","Jesus saw him before he came—do you feel seen and known by God today?","'Come and see'—sometimes a breakthrough of faith begins with being willing to go and look"],
 prayer="Lord, Nathanael had no deceit, and You commended him. Help me live a faith without hypocrisy—honest with You, real with people, willing to come to You even amid doubt. Amen."),
"亚拿尼亚（大马士革）": dict(lesson="Overcoming fear to receive the newly repentant",
 summary="A disciple in Damascus; God called him in a vision to find Saul (Paul); he honestly voiced his fear—Saul had come to persecute Christians—but obeyed at once when God reaffirmed the command, going to Saul, calling him brother, and baptizing him.",
 witness="Ananias said to God: Lord, I have heard from many how much harm this man has done to Your saints in Jerusalem. His fear was real, but he did not let fear stop obedience. He was the first Christian to call Paul 'brother.'",
 follow=["Choosing obedience over self-protection, between God's call and personal fear","Becoming the first willing to receive the repentant, even one who had hurt you","Honestly voicing fear, but not letting fear become a reason for disobedience"],
 caution=[],
 applications=["Ananias' fear was reasonable—is there someone God calls you to reach whom you fear?","He called Saul 'brother'—is there a repentant person you're not yet ready to call 'brother'?","An obedient nobody became key to the restoration of the world's greatest apostle—your obedience may change history too","Do today the one obedience you keep postponing out of fear"],
 prayer="Lord, Ananias was afraid, but went anyway. Help me obey Your call even amid fear, willing to be the first to extend a hand to the repentant. Amen."),
"彼拉多": dict(lesson="Knowing innocence yet compromising for politics",
 summary="Knowing Jesus was innocent, he yet condemned Him to death under political pressure.",
 witness="Pilate's story is a real warning about knowing innocence yet compromising for politics. Compromise of truth is not accepted by God because of political necessity.",
 follow=[],
 caution=["Three times finding no fault—'I find no guilt in him'—yet compromising to sentence Him out of fear of the Jews, Caesar, and unrest","Pretending, by 'washing his hands,' to be uninvolved in shedding innocent blood, self-deceptively shirking responsibility","To keep his political position, going along with the crowd though he knew it was unjust"],
 applications=["Knowing what is right yet not doing it out of fear of people or loss of position is sin (Jas 4:17)","No ritual or excuse can wash away the responsibility of deliberate wrong—'washing hands' fools neither God nor conscience","Between crowd pressure and what is right, ask God for courage not to drift with the tide"],
 prayer="Lord, give me courage before the truth, not compromising under political or social pressure. Amen."),
"该亚法": dict(lesson="Religious garb covering dark motives",
 summary="The high priest who put Jesus to death on religious pretext, yet unwittingly spoke a prophecy.",
 witness="Caiaphas' story is a real warning about religious garb covering dark motives. Religious garb can cover the darkest motives.",
 follow=[],
 caution=["As high priest, condemning the innocent Jesus with the political calculation 'better one man die for the people than the whole nation perish' (John 11:49-50)","Wrapping the dark motive of killing the Son of God in religious garb and legal procedure","Putting the system and his own position above truth, yet unwittingly speaking the prophecy of redemption"],
 applications=["Religious office and correct procedure can be used to cover self-interest—ask God to keep your motives pure","Don't rationalize unjust means with reasons like 'for the greater good' or 'for the church's sake'","Power is most dangerous when it makes us feel we can decide for God who should be sacrificed"],
 prayer="Lord, give me an honest heart, not using religion to cover my selfish desires. Amen."),
"希律": dict(lesson="Power cannot stop God's will",
 summary="He killed the infants of Bethlehem, yet could not stop God's plan.",
 witness="Herod's story is a real warning that power cannot stop God's will. No power, however great, can stop God's will.",
 follow=[],
 caution=["Hearing of a new king's birth, feigning a wish to worship, but really wanting to remove this threat to his throne","To keep his position, ordering all boys two and under in Bethlehem killed—cruel and vicious","Trying to stop God's plan by power and violence, yet God easily preserved Christ through a dream and a journey"],
 applications=["When God raises something new in your life, do you welcome it, or resist out of fear of losing control?","Power not submitted to God drives people to the cruelest acts to 'preserve themselves'","No power can block God's will—rather than resist, bow and worship the true King"],
 prayer="Lord, let me understand that any human power is limited before Your will. Amen."),
"西庇太的儿子们": dict(lesson="From seeking high position to gladly serving",
 summary="James and John sought the seats of honor, and later became a faithful martyr and the apostle of love.",
 witness="The sons of Zebedee's lives hold both an example to follow and a warning to heed. Spiritual growth is a journey from seeking glory to gladly serving.",
 follow=["Called, they at once left their nets and their father Zebedee to follow Jesus (Matt 4:21-22)","James later became the first apostle martyred (Acts 12:2), and John the 'apostle of love,' their ambition for high position refined by God into glad self-denial","Truly drank the 'cup' the Lord spoke of—suffering for the Lord, faithful unto death"],
 caution=["(Through their mother) seeking to sit at the Lord's right and left in His kingdom, their grasping for power angering the other disciples (Matt 20:20-24)","Once asking to 'call down fire from heaven' on a Samaritan village that would not receive them, rebuked by the Lord for their fiery temper (Luke 9:54-55)"],
 applications=["Ambition in following the Lord must be aimed right—not seeking high position, but to drink His cup and gladly serve","Spiritual zeal mixed with the flesh (grasping, revenge) needs to be reshaped by the Lord's love","How much of your service motive today is wanting to be esteemed? Give it to the Lord to refine"],
 prayer="Lord, let my spiritual growth be such a transformation too—from seeking glory to gladly serving. Amen."),
"约翰（启示录）": dict(lesson="Receiving the greatest revelation in suffering and exile",
 summary="The apostle John in old age was exiled to the lonely island of Patmos for his faith; in that isolated, cut-off place he was in the Spirit on the Lord's Day, saw the risen, ascended Christ, and received the longest and grandest revelation in the New Testament—a vision of all future history—passing it to the seven persecuted churches.",
 witness="John opens Revelation: I, John, your brother and partner in the tribulation and the kingdom and the patient endurance that are in Jesus. He speaks not as a leader but as a brother sharing in suffering. The deepest revelation came from the deepest loneliness.",
 follow=["Keeping spiritual sharpness and waiting on God even when isolated and cut off","Using his own suffering to comfort and give hope to fellow sufferers","Faithfully recording and conveying God's revelation, not changing the message under pressure"],
 caution=[],
 applications=["Patmos was a place of exile, yet became a place of revelation—your isolated situation today may be where God speaks to you","John was in the Spirit on the Lord's Day—even in the hardest situation, practicing worship and waiting on God is key","He wrote to seven churches—your witness in suffering today can become strength for others","Is there a lonely season you thought God had forgotten, that you can see anew today?"],
 prayer="Lord, John received the greatest revelation on a lonely island of exile. Help me wait on You in my most isolated, hardest situation today, trusting You still have something to say to me in the dark. Amen."),
"亚撒": dict(lesson="Early reform, later reliance on man",
 summary="A good king of Judah; early on he removed idols and relied on God for victory, but in old age relied on the Aramean king instead of trusting God.",
 witness="Asa's life is a contrast of two phases: his early zeal for reform versus his later reliance on man. His story warns us: spiritual zeal must be sustained for life, not only at the start.",
 follow=["Actively removing idols and restoring worship early on","Seeking God first in crisis"],
 caution=["In old age, relying on a pagan king rather than God before a threat","When the seer rebuked him, growing angry and persecuting the seer"],
 applications=["Examine: is my zeal of faith decreasing with the years?","In every crisis, pray first before seeking human help"],
 prayer="Lord, Asa's later years remind me: faith can't coast on past capital. Help me renew my reliance on You daily, not letting success or age draw me from You. Amen."),
"约坦": dict(lesson="Quiet, faithful, upright leadership",
 summary="A king of Judah who did right and grew steadily stronger—a model of quiet, faithful leadership.",
 witness="Jotham had no dramatic crises or failures, only steady walking before God and growing stronger. Faithfulness is sometimes not dramatic, but quiet and continuous.",
 follow=["Doing right in the LORD's eyes, growing strong because he 'ordered his ways and wholeheartedly obeyed God' (2 Chr 27:6)","Learning from his father Uzziah's trespass into the sanctuary, not repeating the previous generation's pride","Still steadily holding to his right path even amid a still-corrupt people"],
 caution=[],
 applications=["Quietly do the task at hand well, building long-term influence","Examine: do I still do right when no one is watching?"],
 prayer="Lord, Jotham's life tells me: faithfulness need not require big events. Help me quietly walk before You in ordinary days, growing stronger. Amen."),
"亚哈斯": dict(lesson="The consequences of not trusting God but seeking man",
 summary="An evil king of Judah who did not trust God, worshipped idols, and sought help from Assyria, plunging the nation into spiritual and political chaos.",
 witness="Isaiah gave him a chance to ask for a sign; he said: I will not ask. Outwardly pious, in fact rejecting God—trusting Assyria's army more than God's promise.",
 follow=[],
 caution=["In national crisis, not relying on God, but sending the temple's gold and silver to the Assyrian king for help, inviting the wolf in (2 Kgs 16:7-8)","Idolatry to the extreme, even making his son pass through fire per pagan abomination (2 Chr 28:3)","'In the time of his distress he became yet more unfaithful to the LORD'—the more he suffered, the further he drew from God (2 Chr 28:22)"],
 applications=["Pressure most easily exposes who your real god is","In crisis, call God before you call people"],
 prayer="Lord, Ahaz refused Your help. Help me turn to You rather than to man under the greatest pressure. Amen."),
"玛拿西": dict(lesson="Deep sin and great repentance",
 summary="The most evil king in Judah's history, yet under severe punishment he genuinely repented and God restored him—a witness that it is never too late to repent.",
 witness="He did the most evil things; taken captive to Babylon, in his torment he humbled himself greatly and cried out to God. God heard him. This is one of Scripture's most astonishing repentance stories.",
 follow=["Genuinely repenting in deep suffering","After repenting, acting at once to remove idols and restore worship"],
 caution=["Extreme idolatry and evil early on","Corrupting a whole generation spiritually"],
 applications=["No one falls so deep that God cannot restore them","What do you think God cannot forgive you for?"],
 prayer="Lord, Manasseh's repentance tells me: no matter how far I've gone, Your hand can still reach me. Thank You for not giving up on the deepest sinner. Amen."),
"耶罗波安二世": dict(lesson="Material prosperity masking spiritual decay",
 summary="The longest-reigning king of the north, politically and economically prosperous, yet extremely corrupt spiritually—a classic case of strength outside, hollowness within.",
 witness="His era was the north's wealthiest, but Amos cried: your songs are noise, your wealth built on injustice. Prosperity does not equal blessing.",
 follow=[],
 caution=["Reigning 41 years at great political and economic height, expanding territory, yet 'doing evil in the LORD's eyes'—strong outside, hollow within (2 Kgs 14:24)","Prosperity masking social injustice—the very thing Amos and Hosea denounced at this time","Reminding us: national or career prosperity is by no means God's pleasure"],
 applications=["Examine: does my material life mask spiritual barrenness?","Social justice is part of faith, not only personal piety"],
 prayer="Lord, Jeroboam's era warns me: prosperity can be the most beautiful lie. Help me not be deceived by outward success. Amen."),
"何细亚": dict(lesson="Failed leadership before a nation's fall",
 summary="The last king of the north, double-dealing before Assyria, not relying on God, and finally the north fell to Assyria.",
 witness="Facing Assyrian pressure, he paid tribute on one hand and secretly contacted Egypt on the other. This two-faced diplomatic strategy finally led to the north's collapse.",
 follow=[],
 caution=["The last king double-dealing between Assyria and Egypt, seeking survival by scheming, yet not turning back to rely on God (2 Kgs 17:4)","Still not listening before God's final appeal, leading to the north's fall and the ten tribes' scattered exile","Pinning hope on alliances with man rather than God—the spiritual root of national ruin"],
 applications=["Double-dealing in crisis leaves you empty-handed on both sides","What do I tend to rely on under the greatest pressure?"],
 prayer="Lord, Hosea's failure reminds me: in the greatest crisis I cannot rely on playing both sides, only on You. Amen."),
"亚他利雅": dict(lesson="The extreme danger of ambition and lust for power",
 summary="Judah's only queen, who killed the royal heirs and usurped the throne—the most extreme result of unbridled ambition for power.",
 witness="Her ambition drove her to kill her own grandsons to keep power. This is the most extreme case of putting power above God.",
 follow=[],
 caution=["To usurp the throne, exterminating all heirs of Judah's royal line, sparing not even her own grandsons—the extreme of power-lust (2 Kgs 11:1)","Usurping for six years, nearly severing the line of David (on which the Messianic promise rested)","Yet God preserved an heir through the priest hiding Joash—human violence cannot stop God's covenant"],
 applications=["Lust for power is one of the most hidden idols","Power should be a tool for serving, not the ultimate goal"],
 prayer="Lord, Athaliah's story is the deepest warning about power. Help me, in any position, treat power as a tool for serving. Amen."),
"亚玛谢": dict(lesson="The danger of half-heartedness and pride",
 summary="A king of Judah who at first did what pleased God, but worshipped Edom's idols, and after victory proudly provoked the king of Israel, leading to defeat.",
 witness="He defeated Edom, yet brought back Edom's idols to worship. God said: they could not save their own people; how can they save you? Pride blinds.",
 follow=["Doing what pleased God in some ways early on"],
 caution=["Worshipping the useless idols of the enemy he had conquered","Proud after victory, refusing counsel"],
 applications=["The biggest mistakes are easiest to make right after victory","Pride costs you judgment; humility keeps you clear-headed"],
 prayer="Lord, Amaziah grew proud after victory and stubborn before warning. Help me be humbler after success. Amen."),
"约珥": dict(lesson="Repentance brings the Spirit's revival",
 summary="A prophet who called Israel to repent amid a locust plague and national crisis, and prophesied the Pentecost outpouring of the Spirit—a prophet of repentance and hope of revival.",
 witness="Joel saw disaster not as the end but as a call to repent. He prophesied: I will pour out My Spirit on all flesh. On the day of Pentecost, the prophecy came true.",
 follow=["In locust plague and national crisis, calling the whole people to 'rend your hearts, not your garments' and truly return to God (Joel 2:13)","Conveying the great hope that 'God will pour out His Spirit on all flesh,' fulfilled at Pentecost (Joel 2:28; Acts 2:17)","Declaring God 'will restore the years the locusts have eaten'—God can recover lost years (Joel 2:25)"],
 caution=[],
 applications=["Any crisis can be God's call for you to turn back","Rend your heart, not your garments: true repentance starts inside"],
 prayer="Lord, Joel's words are an invitation to revival. Help me see in any hardship Your voice calling me to turn back. Pour out Your Spirit. Amen."),
"阿摩司": dict(lesson="Courageously speaking for social justice",
 summary="A shepherd prophet who raised a cry for social justice at the north's most prosperous time, warning against injustice under false religion.",
 witness="Amos was no professional prophet, but a shepherd. Yet he heard God's call and fearlessly told the powerful: you oppress the poor, and I have seen it all.",
 follow=["A herdsman and dresser of sycamore figs, who went to prophesy when called, answering an unusual call without regard to his background (Amos 7:14-15)","At the north's most prosperous time, denouncing the injustice of oppressing the poor: 'let justice roll on like a river, righteousness like a never-failing stream' (Amos 5:24)","Not retreating when the priest Amaziah threatened him into silence, insisting on speaking only what God entrusted"],
 caution=[],
 applications=["You don't need a special title to answer God's call","Where around you is the vulnerable being oppressed? What can you do?"],
 prayer="Lord, Amos was called from the pasture to proclaim justice. Help me raise a voice for Your justice where I am. Amen."),
"弥迦": dict(lesson="Act justly, love mercy, walk humbly with God",
 summary="A prophet who prophesied the Messiah's birth in Bethlehem and gave the finest summary of faith: act justly, love mercy, and walk humbly with God.",
 witness="Micah distilled the complex religious law into three points: justice, mercy, humility. This is Scripture's most concise, powerful definition of faith.",
 follow=["Speaking for the oppressed and vulnerable, denouncing the powerful who coveted fields and exploited the people (Micah 2:1-2)","Distilling faith into one line: 'act justly, love mercy, and walk humbly with your God' (Micah 6:8)","Prophesying the Messiah would be born in Bethlehem, fulfilled centuries later (Micah 5:2)"],
 caution=[],
 applications=["Practice today: one act of justice, one of mercy, one step of humility","Don't complicate faith: act justly, love mercy, walk humbly"],
 prayer="Lord, Micah 6:8 is Your clearest expectation of me. Help me live out these three things today. Amen."),
"那鸿": dict(lesson="God's justice will surely come",
 summary="A prophet who declared the final judgment of Nineveh (which fell into corruption again about a century later), witnessing the certainty of God's justice.",
 witness="Nineveh repented in Jonah's time, but a century later returned to pride and cruelty. Nahum said: God's patience has an end; justice will surely come.",
 follow=["Faithfully declaring that the once-repentant, again-fallen Nineveh would surely be judged, witnessing 'the LORD will not leave the guilty unpunished' (Nah 1:3)","Under Assyria's boot, bringing oppressed Judah the comfort that 'the LORD is good… He knows those who take refuge in Him' (Nah 1:7)"],
 caution=[],
 applications=["God's patience does not mean God's silence","Don't exploit God's patience to delay real change"],
 prayer="Lord, Nahum tells me Your justice is real. Help me trust Your timing when I face injustice. Amen."),
"哈巴谷": dict(lesson="Holding faith amid doubt",
 summary="A prophet who dared question God about injustice, received God's answer, and finally declared: though the fig tree does not blossom, I will rejoice in God.",
 witness="Habakkuk asked God: why do You not deal with this injustice? God answered, but not as he expected. He still chose to believe. This is the most honest and mature faith.",
 follow=["Daring to ask God honestly 'why do You make me see iniquity, why are You silent,' bringing his confusion straight to God (Hab 1:3,13)","After asking, quietly 'standing at his watchpost' to wait for God's answer, not just talking to himself (Hab 2:1)","In the worst circumstances still declaring 'though the fig tree does not bud… yet I will rejoice in the LORD' (Hab 3:17-18)"],
 caution=[],
 applications=["Questions are not the opposite of faith, but part of it","Though the fig tree does not blossom: can you still trust God in the worst case?"],
 prayer="Lord, Habakkuk, with all his questions, still said: I will rejoice in God. Help me choose joy even when I cannot see You. Amen."),
"西番雅": dict(lesson="Seeking God in distress",
 summary="A prophet who declared judgment while calling Israel to seek God before the day of the LORD, with humility and justice as a refuge.",
 witness="He warned that judgment was coming, yet also said: seek Him before the LORD's anger comes. A call where urgency and hope coexist.",
 follow=["Of royal descent (a descendant of Hezekiah), yet gladly a prophet of God's rebuke, not avoiding hard truth because of status","Declaring 'seek the LORD, seek righteousness and humility,' pointing the remnant to refuge in the day of the LORD (Zeph 2:3)","Ending the message of judgment with promise—'the LORD your God will rejoice over you with gladness, He will quiet you with His love' (Zeph 3:17), conveying mercy within discipline"],
 caution=[],
 applications=["Seek God before distress comes; don't wait until the last moment","Humility and justice are the most secure spiritual protection"],
 prayer="Lord, Zephaniah called the people to seek You before Your day comes. Today I come before You and humble myself. Amen."),
"哈该": dict(lesson="Seek God's kingdom first, not your own comfort",
 summary="A prophet who urged the returned exiles to rebuild the temple first rather than each building their own fine houses—a call to put God's kingdom first.",
 witness="After returning, the people spent sixteen years building their own homes but not God's house. Haggai said: you dwell in paneled houses while this house lies in ruins. His words moved the people to start rebuilding within a month.",
 follow=["Pointing directly at the people's wrong priorities—seeing to their own ceilinged houses while God's house lay in ruins (Hag 1:4)","Calling them to 'consider your ways,' putting God's house first (Hag 1:7)","At his word, Zerubbabel and the people started work at once, with spiritual revival shown within about twenty days (Hag 1:14)"],
 caution=[],
 applications=["Seek first God's kingdom and righteousness: is this your scheduling order?","Do one concrete thing today to put God back first"],
 prayer="Lord, Haggai asked: why does this house lie in ruins? Help me examine my life's priorities, not letting God's things rank below my comfort. Amen."),
"玛拉基": dict(lesson="Return to God, faithful giving",
 summary="The last prophet of the Old Testament, who called the people to return to God, give the tithe honestly, and prophesied the coming of an Elijah-like prophet.",
 witness="Malachi is the Old Testament's final voice: return to Me, and I will return to you. God was still waiting. Then came 400 years of silence, until John appeared.",
 follow=["As the Old Testament's final voice, calling the cold-hearted people to 'return to Me, and I will return to you' (Mal 3:7)","Challenging hearts that discounted their giving: 'bring the full tithe… test Me in this' (Mal 3:10)","Prophesying that the 'sun of righteousness' would rise, and an Elijah-like prophet would prepare the way (Mal 4:2,5)"],
 caution=[],
 applications=["Even in a weary state of faith, God still says: return to Me","Has there been a season you've drifted from God? Return today"],
 prayer="Lord, Malachi is the final invitation to return: return to Me, and I will return to you. Today I choose to return. Amen."),
"沙得拉、米煞、亚伯尼歌": dict(lesson="Absolute faithfulness, even in the furnace",
 summary="Three Hebrew youths refused to bow to the golden image, were thrown into the furnace, and God was with them—unharmed.",
 witness="They said: our God is able to save us; but even if He does not, we will not bow to your golden image. That 'even if' is one of the bravest statements in the history of faith—faithfulness not built on a guarantee that God must rescue.",
 follow=["Still refusing to compromise under the most extreme threat","Faithfulness not conditioned on the outcome","Three of one heart, supporting one another in holding the faith"],
 caution=[],
 applications=["Is your faith conditioned on God's rescue?","'Even if He does not': only the faith that can say this is true faith","Stand against pressure with like-minded believers who strengthen one another"],
 prayer="Lord, the three youths said: even if He does not save us, we will not bow. Help my faith not be conditioned on Your rescue; because You are God, I will obey. Amen."),
"雅亿": dict(lesson="Brave action at the decisive moment",
 summary="An Israelite woman who, when the judge Deborah led Israel to victory, killed the enemy commander Sisera with a tent peg, fulfilling Deborah's prophecy.",
 witness="Jael had no military training, only a tent peg in her hand. But she saw the moment, knew it was God's hour, and acted. God uses ordinary people and ordinary tools to do the extraordinary.",
 follow=["Recognizing the moment God put in her hand, decisively removing the fleeing enemy commander Sisera, fulfilling Deborah's prophecy (Judg 4:21)","Using only the tent peg and hammer at hand to accomplish God's deliverance, praised as 'most blessed of women' (Judg 5:24)"],
 caution=[],
 applications=["God often uses ordinary people at decisive moments","What is in your hand? It may be exactly the tool God will use"],
 prayer="Lord, Jael reminds me: God uses ordinary people who dare to act. Help me recognize the moment You prepare, then act bravely with the tool already in my hand. Amen."),
"亚比该": dict(lesson="Wisdom and mediation resolving conflict",
 summary="Nabal's wife, who by wisdom and initiative stopped David's revenge when her husband's folly provoked him, and later became David's wife.",
 witness="Abigail's wisdom was not mere cleverness, but seeing the matter from God's perspective. She said: do not let David defile his conscience with revenge. She protected David, her husband, and her household at once. True wisdom is win-win-win.",
 follow=["When her foolish husband Nabal offended David and the household faced destruction, not hiding but quickly preparing a gift and going out to defuse it (1 Sam 25:18)","Speaking humbly yet powerfully, urging David not to avenge himself with innocent blood, lest his conscience be burdened later (1 Sam 25:31)","Her wisdom led David to praise 'blessed be your discernment,' avoiding bloodshed (1 Sam 25:33)"],
 caution=[],
 applications=["In a conflict between two sides, you may have a chance to be a wise mediator","Stepping in to defuse conflict beats waiting for tragedy to happen"],
 prayer="Lord, Abigail's wisdom was both humble and powerful. Help me not stand idle in conflict, but have courage to step in and defuse crisis with Your wisdom. Amen."),
"户勒大": dict(lesson="A woman faithfully conveying God's word",
 summary="A prophetess; when King Josiah sent to inquire of God, the priests found Huldah, and she faithfully conveyed God's confirmation of the Book of the Law and His promise to Josiah.",
 witness="When the Book of the Law was found, Josiah sent to inquire of God—and they found a prophetess. Huldah was chosen not because she was a woman, but because she was God's prophet. God used her at history's most critical moment.",
 follow=["When King Josiah sent to inquire, she did not soften the message because the inquirer was a king, faithfully conveying God's judgment and promise (2 Kgs 22:15-20)","In an era when male prophets also served, being trusted and consulted by the king, speaking with authority by God's word"],
 caution=[],
 applications=["God uses people of every background and gender to convey His word","Don't think God can't use you because of low status or because you're a woman"],
 prayer="Lord, Huldah conveyed Your word at history's most critical moment. Help me too, in the place You entrust to me, faithfully convey Your message. Amen."),
"比撒列": dict(lesson="Glorifying God with skill and craft",
 summary="The builder of the tabernacle; God filled him with the Spirit, giving him wisdom, understanding, and every craft to make the sanctuary's furnishings—a pioneer of serving God through art and craft.",
 witness="Bezalel is the first person Scripture explicitly says was filled with the Spirit—not to preach, but to make art and craft. This tells us: skill and craft can be Spirit-filled too, and can be sacred.",
 follow=["'Filled with the Spirit of God, with wisdom, understanding, knowledge, and all craftsmanship'—the first person recorded as Spirit-filled, and it was for craftsmanship (Exod 31:3)","Using gold, silver, bronze, gems, and woodcraft to build the tabernacle, proving craft and art are also holy service to God","Gladly receiving and exercising God's gift, and having a heart to teach others (Exod 35:34)"],
 caution=[],
 applications=["Your professional skill can also be a way of serving God","How can you build God's house with your talents?"],
 prayer="Lord, Bezalel tells me craft too can be Spirit-filled. Help me offer my best skills to You. Amen."),
"示巴女王": dict(lesson="Seeking wisdom, sparing no distance",
 summary="A queen who came from afar to visit Solomon and seek true wisdom; Jesus praised her, saying she would testify against this generation at the judgment.",
 witness="She heard of Solomon's fame, was not content with hearsay, and traveled far to verify it herself. She came with questions, and left saying: the half was not told me. True wisdom humbles. Jesus said she would rise and condemn this generation—because she sought.",
 follow=["Not content with secondhand knowledge, going to seek truth in person","Humbly acknowledging true wisdom when she saw it","Bringing her best gifts to one who was worthy"],
 caution=[],
 applications=["How proactive are you in seeking God's wisdom?","Do you stop at 'hearsay' with others' testimony?","What is the cost of seeking true wisdom today? Are you willing to pay it?"],
 prayer="Lord, the queen of Sheba came from afar to seek wisdom. Help me not be content with secondhand knowledge, but seek You actively until I can say: the half was not told me. Amen."),
"约拿单": dict(lesson="True friendship above self-interest",
 summary="Saul's son, who should have inherited the throne, yet made a covenant with David, protecting him from his father's murder—a model of self-sacrificing friendship.",
 witness="Jonathan was the heir to the throne, but he saw God's choice on David and chose to support David over his own interest. He said: I know my father's heart better than you; I will help you. True friendship is built on God's will, not personal gain.",
 follow=["Putting God's will above personal interest","Risking himself to help his friend at his most dangerous hour","Friendship built on covenant, not convenience"],
 caution=[],
 applications=["True friendship is truest when the other is down","Do you have a friend like Jonathan, willing to sacrifice his own interest?","Reach out today to a friend going through difficulty"],
 prayer="Lord, Jonathan's friendship is one of Scripture's most beautiful pictures. Help me be the kind who is willing to sacrifice his own interest when a friend most needs it. Amen."),
"五饼二鱼的男孩": dict(lesson="Give all you have to Jesus",
 summary="An unnamed boy who gave his five barley loaves and two fish to Jesus, and the miracle of feeding the five thousand followed.",
 witness="The disciples saw five thousand and said: there isn't enough food. The boy gave away all he had—five loaves and two fish. Not half, not keeping a little back. Jesus took, gave thanks, and distributed. The small, fully given, became more than enough in God's hands.",
 follow=["Giving Jesus all his five loaves and two fish, leaving no backup for himself (John 6:9)","Not shrinking back at 'what is this for so many'—a tiny offering in the Lord's hands fed five thousand"],
 caution=[],
 applications=["God's question is not: how much do you have? but: how much will you give?","Give the smallest thing in your hand fully, and see what God can do","Is there a 'five loaves' you've never given to God?"],
 prayer="Lord, the boy gave You all he had. Help me give not just a part, but place all in my hand into Yours, trusting You can multiply it. Amen."),
"寡妇的两个小钱": dict(lesson="Giving all surpasses giving from surplus",
 summary="A poor widow who put two small coins into the temple treasury, praised by Jesus as giving more than all the rich, because she put in all she had to live on.",
 witness="The rich gave from surplus; she gave her all. Jesus called the disciples over and pointed out this moment. He commented on none of the rich givers, but specially praised this nameless widow. God measures the proportion, not the amount.",
 follow=["Putting in 'all she had to live on'—the measure of giving is not the amount but what's left behind (Luke 21:4)","Not feeling unworthy to give because she was poor, trusting God's provision over clutching her own security"],
 caution=[],
 applications=["Is your giving today from surplus, or your all?","God sees your giving even when no one notices","Is there something smaller than two coins you haven't yet given?"],
 prayer="Lord, the widow's two small coins were more than all the rich. Help me give not from surplus, but trusting You will provide. Amen."),
"被洁净的麻疯病人": dict(lesson="Gratitude is the first response to grace",
 summary="Ten lepers were cleansed by Jesus, but only one returned to fall at Jesus' feet in thanks—and he was a Samaritan.",
 witness="Ten were cleansed alike; nine kept going, one returned to fall at Jesus' feet in thanks. Jesus said: where are the other nine? Gratitude is not mere courtesy, but an act of faith that recognizes the source of grace. He returned because he knew who had cleansed him.",
 follow=["Of the ten cleansed, only he 'when he saw he was healed, turned back and loudly glorified God' (Luke 17:15)","Not letting the thrill of healing or busyness crowd out gratitude, falling at the Lord's feet to give thanks","Being a despised Samaritan, yet the one who knew to turn back and give thanks"],
 caution=[],
 applications=["What was your most recent miraculous grace? Did you give thanks?","Find one thing each day to thank God for concretely","Gratitude is a mark of mature faith"],
 prayer="Lord, the one Samaritan who returned reminds me: gratitude is not an add-on, but the heart of faith. Help me be the one who turns back. Amen."),
"那路加福音的悔改税吏": dict(lesson="Humble confession finds God's favor",
 summary="In Jesus' parable, a tax collector simply beat his chest and prayed: God, have mercy on me, a sinner—and was declared more justified before God than the Pharisee.",
 witness="The Pharisee detailed his virtues; the tax collector only bowed his head, beat his chest, and said: God, have mercy on me, a sinner. Jesus said: this man went home more justified than the other. Humble confession is the door to God hearing prayer.",
 follow=["Standing far off, not even daring to lift his eyes, only beating his chest: 'God, have mercy on me, a sinner' (Luke 18:13)","Beginning prayer by admitting his sin rather than listing his righteousness—and this man went home justified"],
 caution=[],
 applications=["Is your prayer today more like the Pharisee or the tax collector?","Sincere confession before God is more accepted than all religious acts","Say only this today: God, have mercy on me, a sinner"],
 prayer="Lord, the tax collector's prayer was the shortest and truest. Today I too say only: God, have mercy on me, a sinner. Amen."),
"撒该": dict(lesson="Jesus actively seeks the lost",
 summary="A chief tax collector who, being short, climbed a sycamore to see Jesus; Jesus invited Himself to his home, and he repented, repaying fourfold.",
 witness="Zacchaeus did not go to meet Jesus; he only wanted to see who Jesus was. But Jesus said: today I must stay at your house. Jesus sought Zacchaeus first. Repentance happened after Jesus' initiative and coming.",
 follow=["After repenting, taking concrete action of restitution at once","Doing more than required: repaying fourfold"],
 caution=["Previously gathering wealth by unjust means"],
 applications=["Jesus is actively seeking you today too","True repentance brings concrete change of action","Is there something you need to return or make restitution for?"],
 prayer="Lord, Jesus sought Zacchaeus first, not waiting for him to clean up. Thank You for seeking me. Help me, like Zacchaeus, have real change after Your coming. Amen."),
"好撒玛利亚人": dict(lesson="Your neighbor is the one in need before you",
 summary="In Jesus' parable, a Samaritan saw a wounded robbery victim and, at his own expense, gave time and money to help him—becoming the definition of 'love your neighbor as yourself.'",
 witness="The priest and Levite saw and passed by; the Samaritan saw and was moved with compassion. The same seeing, a different choice. Love is not feeling, but action. The good Samaritan did not ask who the man was—he helped first.",
 follow=["Seeing the robbed stranger and being 'moved with compassion,' going at once to bind his wounds, pouring on oil and wine (Luke 10:33-34)","Spending his own animal, money, and time, taking the man to an inn and prepaying further costs (Luke 10:35)","Loving across barriers of race and religion, redefining 'who is my neighbor'"],
 caution=[],
 applications=["Who before you needs your help today?","Love your neighbor as yourself: who is your neighbor?","Don't leave helping someone to 'a later chance'"],
 prayer="Lord, the good Samaritan was moved with compassion and then acted. Help me not only feel sympathy, but help in action the one in need before me. Amen."),
"伯大尼的抹香妇人": dict(lesson="Great forgiveness yields great love",
 summary="A woman with a sinful reputation who anointed Jesus' feet with tears and perfume in a Pharisee's house; Jesus praised her: her many sins are forgiven, for she loved much.",
 witness="The Pharisee thought: if this man were a prophet, he would know who is touching him. But Jesus said to the woman: your sins are forgiven; your faith has saved you. She loved much because she knew how much she had been forgiven. Only those who deeply know their need of grace can love most deeply.",
 follow=["Loving with all her heart even under others' critical eyes","Offering Jesus her most precious gift","Real gratitude for the fact of being forgiven"],
 caution=[],
 applications=["Do you know how much you have been forgiven?","The deeper your awareness of your sin, the greater your love for God","How will you express your love for Jesus today?"],
 prayer="Lord, the woman's tears and perfume were her most beautiful confession of love for You. Help me know deeply how much I am forgiven, turning that knowledge into love for You. Amen."),
}
